INSERT INTO content_items (id, topic_id, source_id, url, raw_text, clean_text, content_hash, language, captured_at, credibility_score_at_capture, narrative_cluster_id, labels, created_at, updated_at, org_id) VALUES
('hr-ci-01','hr-stf-001','hr-src-01','https://tribuneindia.com/haryana-drug-seizure-nh44','Major drug seizure on NH-44 near Ambala','STF Haryana seizes 15 kg heroin worth Rs 75 crore from a truck on NH-44 near Ambala Cantt toll plaza. Two Punjab residents arrested. Consignment was being transported from Amritsar to Delhi via Haryana. STF acted on intelligence input from NCB.', md5('hr-ci-01'),'en',NOW()-INTERVAL '28 days',82.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Tribune India","author_id":"hr-src-01","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.5,"label":"negative"},"keywords":["heroin","seizure","NH-44","Ambala","STF","NCB"]}'::jsonb,NOW()-INTERVAL '28 days',NOW(),'org_cyber'),
('hr-ci-02','hr-stf-001','hr-src-03','https://hindustantimes.com/chandigarh/karnal-poppy-husk','Poppy husk worth Rs 2 crore seized in Karnal','Haryana Police STF intercepts truck carrying 500 kg poppy husk (bhukki) near Karnal bypass. Driver fled, abandoned vehicle. Consignment traced to Rajasthan via GPS tracking. Second major seizure this month on NH-44 corridor.', md5('hr-ci-02'),'en',NOW()-INTERVAL '27 days',80.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Hindustan Times","author_id":"hr-src-03","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.45,"label":"negative"},"keywords":["poppy husk","Karnal","STF","Rajasthan","NH-44"]}'::jsonb,NOW()-INTERVAL '27 days',NOW(),'org_cyber'),
('hr-ci-03','hr-stf-001','hr-src-06','https://t.me/punjab_drug_watch/234','New route via Patiala-Panchkula bypass','ALERT: Smugglers using new route via Patiala-Panchkula bypass road to avoid NH-44 checkpoints. Smaller quantities in private cars instead of trucks. Contact for info: +91-98765-11111.', md5('hr-ci-03'),'en',NOW()-INTERVAL '26 days',20.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@punjab_drug_watch","author_id":"punjab_drug_watch","engagement":{"likes":12,"comments":34,"shares":0,"views":560,"forwards":15},"sentiment":{"compound":-0.7,"label":"negative"},"keywords":["new route","Patiala","Panchkula","bypass","smugglers"]}'::jsonb,NOW()-INTERVAL '26 days',NOW(),'org_cyber'),
('hr-ci-04','hr-stf-001','hr-src-07','https://t.me/haryana_crime_updates/567','Toll plaza checkpoint surprise raid','STF conducts surprise raid at Shahabad toll plaza on NH-152. 3 vehicles checked, 2 kg synthetic drugs recovered from hidden compartment. Modus operandi: drugs concealed in modified fuel tank.', md5('hr-ci-04'),'en',NOW()-INTERVAL '25 days',25.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@haryana_crime_updates","author_id":"haryana_crime_updates","engagement":{"likes":23,"comments":45,"shares":0,"views":890,"forwards":18},"sentiment":{"compound":-0.55,"label":"negative"},"keywords":["STF","raid","Shahabad","synthetic drugs","toll plaza"]}'::jsonb,NOW()-INTERVAL '25 days',NOW(),'org_cyber'),
('hr-ci-05','hr-stf-001','hr-src-02','https://jagran.com/haryana-drug-corridor-analysis','Drug corridor analysis: Punjab to Delhi via Haryana','Dainik Jagran investigative report: Haryana has become the primary transit corridor for drugs from Punjab to Delhi-NCR. NH-44 and NH-152 are the main arteries. Over 200 kg narcotics seized in last 6 months. STF sources say for every seizure, 10x gets through.', md5('hr-ci-05'),'en',NOW()-INTERVAL '23 days',75.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Dainik Jagran","author_id":"hr-src-02","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.6,"label":"negative"},"keywords":["drug corridor","Punjab","Delhi","NH-44","NH-152","transit"]}'::jsonb,NOW()-INTERVAL '23 days',NOW(),'org_cyber'),
('hr-ci-06','hr-stf-001','hr-src-08','https://t.me/ncr_underground_intel/89','Delhi receiver network exposed','NCR network: Delhi-based receiver identified. Uses Telegram handles @delhimaaldrop and @ncr_supply_786. Coordinates with Punjab suppliers via encrypted channels. Drops in Sonipat and Panipat. Phone: +91-98765-22222.', md5('hr-ci-06'),'en',NOW()-INTERVAL '22 days',15.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@ncr_underground_intel","author_id":"ncr_underground_intel","engagement":{"likes":5,"comments":15,"shares":0,"views":340,"forwards":8},"sentiment":{"compound":-0.75,"label":"negative"},"keywords":["Delhi","receiver","Telegram","Sonipat","Panipat","network"]}'::jsonb,NOW()-INTERVAL '22 days',NOW(),'org_cyber'),
('hr-ci-07','hr-stf-001','hr-src-04','https://amarujala.com/haryana-bsf-drug-seizure','BSF seizes heroin at Fazilka-Sirsa border','BSF troops seized 5 kg heroin worth Rs 25 crore near Fazilka-Sirsa border sector. Drone was used to drop narcotics from Pakistan side. Second drone-based smuggling attempt this month.', md5('hr-ci-07'),'en',NOW()-INTERVAL '20 days',72.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Amar Ujala","author_id":"hr-src-04","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.65,"label":"negative"},"keywords":["BSF","heroin","Fazilka","Sirsa","drone","Pakistan"]}'::jsonb,NOW()-INTERVAL '20 days',NOW(),'org_cyber'),
('hr-ci-08','hr-stf-001','hr-src-05','https://indianexpress.com/haryana-stf-network-busted','Inter-state drug network busted by STF','Indian Express: STF Haryana busts inter-state drug network operating across Punjab, Haryana, and Rajasthan. 8 arrested including kingpin from Amritsar. Rs 50 crore worth narcotics seized over 3-month operation. Network used hawala for payments.', md5('hr-ci-08'),'en',NOW()-INTERVAL '18 days',78.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Indian Express","author_id":"hr-src-05","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.5,"label":"negative"},"keywords":["STF","network busted","Punjab","Rajasthan","hawala","kingpin"]}'::jsonb,NOW()-INTERVAL '18 days',NOW(),'org_cyber'),
('hr-ci-09','hr-stf-001','hr-src-09','https://t.me/chitta_alert_hrpb/45','Chitta supply line from Ludhiana','WARNING: New chitta supply line established from Ludhiana to Ambala via Rajpura. Small-time peddlers using auto-rickshaws. Contact +91-98765-11111 for updates. Price drop indicates increased supply.', md5('hr-ci-09'),'en',NOW()-INTERVAL '16 days',12.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@chitta_alert_hrpb","author_id":"chitta_alert_hrpb","engagement":{"likes":8,"comments":20,"shares":0,"views":430,"forwards":10},"sentiment":{"compound":-0.8,"label":"negative"},"keywords":["chitta","Ludhiana","Ambala","Rajpura","supply line","peddlers"]}'::jsonb,NOW()-INTERVAL '16 days',NOW(),'org_cyber'),
('hr-ci-10','hr-stf-001','hr-src-10','https://haryanapolice.gov.in/press-release-drug-ops','Haryana Police press release: Q2 drug operations','Official press release: Haryana Police STF conducted 142 operations in Q2 2026. Total seizures: 85 kg heroin, 1200 kg poppy husk, 15 kg synthetic drugs. 234 persons arrested under NDPS Act. Conviction rate 78%.', md5('hr-ci-10'),'en',NOW()-INTERVAL '14 days',90.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Haryana Police","author_id":"hr-src-10","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.1,"label":"neutral"},"keywords":["STF","operations","seizures","heroin","NDPS","conviction"]}'::jsonb,NOW()-INTERVAL '14 days',NOW(),'org_cyber'),
('hr-ci-11','hr-stf-001','hr-src-06','https://t.me/punjab_drug_watch/250','Ambala railway station interception','Drug mule intercepted at Ambala Cantt railway station. 1.5 kg heroin found in specially stitched jacket lining. Mule was traveling from Jalandhar to Delhi on Shatabdi Express. Contact: +91-98765-22222.', md5('hr-ci-11'),'en',NOW()-INTERVAL '12 days',20.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@punjab_drug_watch","author_id":"punjab_drug_watch","engagement":{"likes":15,"comments":28,"shares":0,"views":670,"forwards":12},"sentiment":{"compound":-0.6,"label":"negative"},"keywords":["drug mule","Ambala","railway","heroin","Jalandhar","Delhi"]}'::jsonb,NOW()-INTERVAL '12 days',NOW(),'org_cyber'),
('hr-ci-12','hr-stf-001','hr-src-11','https://narcoticsindia.nic.in/haryana-coordination','NCB coordination meeting on Haryana drug menace','NCB convenes coordination meeting with Haryana STF, Punjab Police, and BSF. Focus on dismantling Afghan heroin pipeline through Punjab-Haryana corridor. Multi-agency task force proposed.', md5('hr-ci-12'),'en',NOW()-INTERVAL '10 days',92.0,'hr-cl-01','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"NCB India","author_id":"hr-src-11","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.2,"label":"negative"},"keywords":["NCB","coordination","STF","Punjab","BSF","Afghan heroin"]}'::jsonb,NOW()-INTERVAL '10 days',NOW(),'org_cyber'),

