('hr-ci-13','hr-stf-001','hr-src-01','https://tribuneindia.com/chitta-epidemic-ambala','Chitta claims 3 more lives in Ambala','Tribune India: Three youth from Ambala Sadar area die of chitta overdose within a week. Families blame easy availability and police inaction. Local MLA demands emergency measures. Hospital reports 50% rise in drug overdose cases.', md5('hr-ci-13'),'en',NOW()-INTERVAL '26 days',82.0,'hr-cl-02','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Tribune India","author_id":"hr-src-01","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.85,"label":"negative"},"keywords":["chitta","overdose","Ambala","youth","deaths","epidemic"]}'::jsonb,NOW()-INTERVAL '26 days',NOW(),'org_cyber'),
('hr-ci-14','hr-stf-001','hr-src-07','https://t.me/haryana_crime_updates/580','Karnal rehab center overwhelmed','Karnal district drug rehabilitation center overwhelmed — 200% capacity. Patients sleeping on floors. Most admissions are chitta users aged 18-25. Government funding inadequate. NGOs stepping in.', md5('hr-ci-14'),'en',NOW()-INTERVAL '24 days',25.0,'hr-cl-02','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@haryana_crime_updates","author_id":"haryana_crime_updates","engagement":{"likes":45,"comments":67,"shares":0,"views":1500,"forwards":22},"sentiment":{"compound":-0.7,"label":"negative"},"keywords":["Karnal","rehabilitation","chitta","youth","overcrowded"]}'::jsonb,NOW()-INTERVAL '24 days',NOW(),'org_cyber'),
('hr-ci-15','hr-stf-001','hr-src-03','https://hindustantimes.com/chandigarh/chitta-schools','Chitta reaches school gates in Ambala','Hindustan Times investigation: Chitta peddlers operating near school gates in Ambala and Karnal. Students as young as 15 being targeted. Parents form vigilante groups. Police promise crackdown but community skeptical.', md5('hr-ci-15'),'en',NOW()-INTERVAL '22 days',80.0,'hr-cl-02','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Hindustan Times","author_id":"hr-src-03","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.9,"label":"negative"},"keywords":["chitta","schools","Ambala","Karnal","peddlers","students"]}'::jsonb,NOW()-INTERVAL '22 days',NOW(),'org_cyber'),
('hr-ci-16','hr-stf-001','hr-src-09','https://t.me/chitta_alert_hrpb/50','Chitta price crash — supply surge','Chitta price crashed from Rs 5000/gram to Rs 2000/gram in Ambala. Indicates massive supply surge. New batch entering from Punjab. Quality also degrading — more adulterants, higher overdose risk.', md5('hr-ci-16'),'en',NOW()-INTERVAL '20 days',12.0,'hr-cl-02','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@chitta_alert_hrpb","author_id":"chitta_alert_hrpb","engagement":{"likes":10,"comments":25,"shares":0,"views":380,"forwards":14},"sentiment":{"compound":-0.75,"label":"negative"},"keywords":["chitta","price","supply","Ambala","Punjab","adulterants"]}'::jsonb,NOW()-INTERVAL '20 days',NOW(),'org_cyber'),
('hr-ci-17','hr-stf-001','hr-src-02','https://jagran.com/haryana-chitta-deaths-karnal','12 chitta deaths in Karnal in one month','Dainik Jagran: Karnal district records 12 deaths from chitta overdose in one month. CM orders inquiry. Health department sets up special detox ward. Opposition demands white paper on drug menace.', md5('hr-ci-17'),'en',NOW()-INTERVAL '18 days',75.0,'hr-cl-02','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Dainik Jagran","author_id":"hr-src-02","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.8,"label":"negative"},"keywords":["chitta","deaths","Karnal","CM","inquiry","detox"]}'::jsonb,NOW()-INTERVAL '18 days',NOW(),'org_cyber'),
('hr-ci-18','hr-stf-001','hr-src-06','https://t.me/punjab_drug_watch/245','Chitta lab busted near Yamunanagar','Underground chitta processing lab busted near Yamunanagar. Raw opium from Rajasthan processed into chitta. 3 arrested including chemistry graduate. Lab equipment worth Rs 50 lakh seized.', md5('hr-ci-18'),'en',NOW()-INTERVAL '16 days',20.0,'hr-cl-02','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@punjab_drug_watch","author_id":"punjab_drug_watch","engagement":{"likes":18,"comments":30,"shares":0,"views":720,"forwards":16},"sentiment":{"compound":-0.65,"label":"negative"},"keywords":["chitta lab","Yamunanagar","opium","Rajasthan","processing"]}'::jsonb,NOW()-INTERVAL '16 days',NOW(),'org_cyber'),
('hr-ci-19','hr-stf-001','hr-src-04','https://amarujala.com/haryana-mothers-anti-drug','Mothers Against Drugs rally in Panchkula','Amar Ujala: Hundreds of mothers march in Panchkula demanding strict action against drug peddlers. Carry photographs of children lost to chitta. Demand NDPS Act be applied without bail provisions.', md5('hr-ci-19'),'en',NOW()-INTERVAL '14 days',72.0,'hr-cl-02','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Amar Ujala","author_id":"hr-src-04","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.3,"label":"negative"},"keywords":["mothers","rally","Panchkula","chitta","NDPS","peddlers"]}'::jsonb,NOW()-INTERVAL '14 days',NOW(),'org_cyber'),
('hr-ci-20','hr-stf-001','hr-src-08','https://t.me/ncr_underground_intel/95','Synthetic drug alternative emerging','New synthetic drug "party powder" emerging as chitta alternative in Haryana colleges. Cheaper at Rs 500/dose. Sold via Instagram DMs. Chemical composition unknown. Two hospitalized in Kurukshetra after use.', md5('hr-ci-20'),'en',NOW()-INTERVAL '11 days',15.0,'hr-cl-02','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@ncr_underground_intel","author_id":"ncr_underground_intel","engagement":{"likes":6,"comments":18,"shares":0,"views":290,"forwards":7},"sentiment":{"compound":-0.7,"label":"negative"},"keywords":["synthetic drug","party powder","colleges","Instagram","Kurukshetra"]}'::jsonb,NOW()-INTERVAL '11 days',NOW(),'org_cyber'),
('hr-ci-21','hr-stf-001','hr-src-05','https://indianexpress.com/haryana-drug-rehab-expansion','Haryana announces 5 new drug rehab centers','Indian Express: Haryana government announces 5 new drug rehabilitation centers in Ambala, Karnal, Panchkula, Hisar, and Rohtak. Rs 100 crore allocated. Each center to have 200-bed capacity. Operational by December.', md5('hr-ci-21'),'en',NOW()-INTERVAL '8 days',78.0,'hr-cl-02','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Indian Express","author_id":"hr-src-05","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.3,"label":"positive"},"keywords":["rehabilitation","centers","Ambala","Karnal","Panchkula","government"]}'::jsonb,NOW()-INTERVAL '8 days',NOW(),'org_cyber'),
('hr-ci-22','hr-stf-001','hr-src-07','https://t.me/haryana_crime_updates/595','Village sarpanch leads anti-drug patrol','Sarpanch of village near Ambala organizes nightly patrols to catch drug peddlers. Community vigilance committees formed in 15 villages. Two peddlers caught and handed to police. Model being replicated.', md5('hr-ci-22'),'en',NOW()-INTERVAL '5 days',25.0,'hr-cl-02','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@haryana_crime_updates","author_id":"haryana_crime_updates","engagement":{"likes":56,"comments":34,"shares":0,"views":1200,"forwards":20},"sentiment":{"compound":0.2,"label":"positive"},"keywords":["sarpanch","anti-drug","patrol","community","Ambala","vigilance"]}'::jsonb,NOW()-INTERVAL '5 days',NOW(),'org_cyber'),

