('hr-ci-23','hr-stf-001','hr-src-10','https://haryanapolice.gov.in/stf-operation-thunder','Operation Thunder: STF arrests 15 drug lords','Haryana Police press release: Operation Thunder conducted across 8 districts simultaneously. 15 drug lords arrested including 3 absconders. Rs 120 crore worth narcotics seized. Inter-state coordination with Punjab, Rajasthan, and Delhi Police.', md5('hr-ci-23'),'en',NOW()-INTERVAL '24 days',90.0,'hr-cl-03','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Haryana Police","author_id":"hr-src-10","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.3,"label":"negative"},"keywords":["Operation Thunder","STF","arrests","drug lords","seizure"]}'::jsonb,NOW()-INTERVAL '24 days',NOW(),'org_cyber'),
('hr-ci-24','hr-stf-001','hr-src-01','https://tribuneindia.com/stf-ambala-kingpin','STF arrests Ambala drug kingpin','Tribune India: STF arrests Ambala-based drug kingpin Sukhwinder alias Sukhi who had been operating for 8 years. Network spread across 3 states. Rs 15 crore cash and 10 kg heroin recovered. Was using Telegram for coordination.', md5('hr-ci-24'),'en',NOW()-INTERVAL '22 days',82.0,'hr-cl-03','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Tribune India","author_id":"hr-src-01","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.4,"label":"negative"},"keywords":["STF","kingpin","Ambala","Sukhwinder","heroin","Telegram"]}'::jsonb,NOW()-INTERVAL '22 days',NOW(),'org_cyber'),
('hr-ci-25','hr-stf-001','hr-src-07','https://t.me/haryana_crime_updates/575','Financial trail reveals hawala network','STF investigation into drug money trail reveals hawala network operating from Panchkula. Money routed through Dubai to Pakistan. 4 hawala operators arrested. Bank accounts worth Rs 8 crore frozen under PMLA.', md5('hr-ci-25'),'en',NOW()-INTERVAL '20 days',25.0,'hr-cl-03','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@haryana_crime_updates","author_id":"haryana_crime_updates","engagement":{"likes":34,"comments":56,"shares":0,"views":1100,"forwards":25},"sentiment":{"compound":-0.55,"label":"negative"},"keywords":["hawala","Panchkula","drug money","Dubai","PMLA","bank accounts"]}'::jsonb,NOW()-INTERVAL '20 days',NOW(),'org_cyber'),
('hr-ci-26','hr-stf-001','hr-src-03','https://hindustantimes.com/chandigarh/stf-panchkula-raid','STF raids Panchkula farmhouse, seizes synthetic drugs','Hindustan Times: STF raids luxury farmhouse in Panchkula sector 20. 8 kg MDMA and 2 kg cocaine seized. Farmhouse owner arrested — retired army officer turned drug supplier. Party drugs being supplied to Chandigarh nightclubs.', md5('hr-ci-26'),'en',NOW()-INTERVAL '17 days',80.0,'hr-cl-03','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Hindustan Times","author_id":"hr-src-03","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.5,"label":"negative"},"keywords":["STF","raid","Panchkula","MDMA","cocaine","farmhouse"]}'::jsonb,NOW()-INTERVAL '17 days',NOW(),'org_cyber'),
('hr-ci-27','hr-stf-001','hr-src-12','https://youtube.com/watch?v=stf_press_conf','STF press conference: Major operation results','Haryana STF IG addresses press conference on Operation Thunder results. Details 3-month intelligence operation. 47 accused identified, 15 arrested, 32 still at large. Appeals for public cooperation. Announces anonymous tip hotline.', md5('hr-ci-27'),'en',NOW()-INTERVAL '15 days',85.0,'hr-cl-03','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Haryana Police Press","author_id":"hr-src-12","engagement":{"likes":120,"comments":45,"shares":30,"views":8500},"sentiment":{"compound":-0.2,"label":"negative"},"keywords":["STF","press conference","Operation Thunder","IG","anonymous tip"]}'::jsonb,NOW()-INTERVAL '15 days',NOW(),'org_cyber'),
('hr-ci-28','hr-stf-001','hr-src-08','https://t.me/ncr_underground_intel/92','Dark web drug market targeting Haryana','Dark web marketplace listing heroin and synthetic drugs with Haryana delivery. Seller uses moniker "PunjabPharma420". Accepts crypto only. Ships via India Post in disguised packages. Active since 3 months.', md5('hr-ci-28'),'en',NOW()-INTERVAL '13 days',15.0,'hr-cl-03','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@ncr_underground_intel","author_id":"ncr_underground_intel","engagement":{"likes":3,"comments":10,"shares":0,"views":220,"forwards":5},"sentiment":{"compound":-0.8,"label":"negative"},"keywords":["dark web","heroin","synthetic drugs","crypto","India Post"]}'::jsonb,NOW()-INTERVAL '13 days',NOW(),'org_cyber'),
('hr-ci-29','hr-stf-001','hr-src-02','https://jagran.com/haryana-stf-women-gang','STF busts all-women drug courier gang','Dainik Jagran: STF busts all-women drug courier gang operating in Ambala-Karnal sector. 6 women arrested, used to carry drugs in modified handbags and undergarments. Gang was operational for 2 years.', md5('hr-ci-29'),'en',NOW()-INTERVAL '10 days',75.0,'hr-cl-03','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Dainik Jagran","author_id":"hr-src-02","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.45,"label":"negative"},"keywords":["STF","women","courier","gang","Ambala","Karnal"]}'::jsonb,NOW()-INTERVAL '10 days',NOW(),'org_cyber'),
('hr-ci-30','hr-stf-001','hr-src-04','https://amarujala.com/haryana-ndps-court','Fast-track NDPS courts announced for Haryana','Amar Ujala: High Court approves 3 fast-track NDPS courts in Ambala, Karnal, and Panchkula. Will expedite drug case trials. Currently 4,500 pending NDPS cases in Haryana. Average case takes 3 years for conviction.', md5('hr-ci-30'),'en',NOW()-INTERVAL '7 days',72.0,'hr-cl-03','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Amar Ujala","author_id":"hr-src-04","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.15,"label":"neutral"},"keywords":["NDPS","courts","fast-track","Ambala","Karnal","Panchkula"]}'::jsonb,NOW()-INTERVAL '7 days',NOW(),'org_cyber'),
('hr-ci-31','hr-stf-001','hr-src-06','https://t.me/punjab_drug_watch/260','STF informant network expanding','STF building informant network in border villages. Offering cash rewards for actionable intelligence. Phone: +91-98765-33333. Anonymity guaranteed. Focus on Ambala, Karnal, Kurukshetra districts.', md5('hr-ci-31'),'en',NOW()-INTERVAL '4 days',20.0,'hr-cl-03','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@punjab_drug_watch","author_id":"punjab_drug_watch","engagement":{"likes":10,"comments":15,"shares":0,"views":450,"forwards":8},"sentiment":{"compound":0.1,"label":"neutral"},"keywords":["STF","informant","intelligence","Ambala","Karnal","Kurukshetra"]}'::jsonb,NOW()-INTERVAL '4 days',NOW(),'org_cyber'),
('hr-ci-32','hr-stf-001','hr-src-05','https://indianexpress.com/haryana-stf-tech','STF adopts AI-driven surveillance','Indian Express: Haryana STF adopts technology-driven approach. Using ANPR cameras at toll plazas, social media monitoring, and AI-driven surveillance for tracking drug networks. Rs 10 crore budget allocated.', md5('hr-ci-32'),'en',NOW()-INTERVAL '2 days',78.0,'hr-cl-03','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Indian Express","author_id":"hr-src-05","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.25,"label":"positive"},"keywords":["STF","AI","surveillance","ANPR","social media","technology"]}'::jsonb,NOW()-INTERVAL '2 days',NOW(),'org_cyber'),

