('hr-ci-33','hr-stf-001','hr-src-11','https://narcoticsindia.nic.in/afghan-heroin-pipeline','NCB report: Afghan heroin pipeline through India','NCB intelligence report: Afghan heroin enters India via Pakistan-Punjab border. Routed through Amritsar-Jalandhar-Ambala-Delhi pipeline. Haryana is the critical transit zone. Estimated 30 tons annual flow through this corridor.', md5('hr-ci-33'),'en',NOW()-INTERVAL '25 days',92.0,'hr-cl-04','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"NCB India","author_id":"hr-src-11","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.5,"label":"negative"},"keywords":["Afghan heroin","pipeline","Pakistan","Punjab","Amritsar","corridor"]}'::jsonb,NOW()-INTERVAL '25 days',NOW(),'org_cyber'),
('hr-ci-34','hr-stf-001','hr-src-08','https://t.me/ncr_underground_intel/88','Cross-border drone drops increasing','Cross-border drone drops of heroin increasing along Punjab border. 15 drone incidents in last 2 months. Payloads of 5-10 kg each. Drones purchased from China via dark web. GPS coordinates shared via Telegram.', md5('hr-ci-34'),'en',NOW()-INTERVAL '23 days',15.0,'hr-cl-04','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@ncr_underground_intel","author_id":"ncr_underground_intel","engagement":{"likes":7,"comments":12,"shares":0,"views":380,"forwards":9},"sentiment":{"compound":-0.7,"label":"negative"},"keywords":["drone","heroin","Punjab border","China","GPS","Telegram"]}'::jsonb,NOW()-INTERVAL '23 days',NOW(),'org_cyber'),
('hr-ci-35','hr-stf-001','hr-src-01','https://tribuneindia.com/bsf-anti-drone','BSF deploys anti-drone system at Punjab border','Tribune India: BSF deploys anti-drone detection and jamming system along Haryana-Punjab border sector. System can detect drones up to 4 km range. 3 drones neutralized in first week of deployment.', md5('hr-ci-35'),'en',NOW()-INTERVAL '20 days',82.0,'hr-cl-04','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Tribune India","author_id":"hr-src-01","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.1,"label":"neutral"},"keywords":["BSF","anti-drone","Punjab border","detection","jamming"]}'::jsonb,NOW()-INTERVAL '20 days',NOW(),'org_cyber'),
('hr-ci-36','hr-stf-001','hr-src-09','https://t.me/chitta_alert_hrpb/55','Smuggling via agricultural trucks','New MO: drugs hidden in agricultural produce trucks (wheat, sugarcane). Punjab farmers recruited as unwitting carriers. Drugs placed in grain sacks without driver knowledge. Phone contact: +91-98765-11111.', md5('hr-ci-36'),'en',NOW()-INTERVAL '17 days',12.0,'hr-cl-04','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@chitta_alert_hrpb","author_id":"chitta_alert_hrpb","engagement":{"likes":12,"comments":22,"shares":0,"views":510,"forwards":11},"sentiment":{"compound":-0.6,"label":"negative"},"keywords":["smuggling","agricultural","trucks","wheat","farmers","Punjab"]}'::jsonb,NOW()-INTERVAL '17 days',NOW(),'org_cyber'),
('hr-ci-37','hr-stf-001','hr-src-03','https://hindustantimes.com/chandigarh/pak-handler','Pakistan-based handler coordinating Haryana supply','Hindustan Times exclusive: NIA investigation reveals Pakistan-based handler coordinating drug supply to Haryana via Punjab. Uses encrypted communication apps. 3 Indian agents identified, 1 arrested in Ambala.', md5('hr-ci-37'),'en',NOW()-INTERVAL '14 days',80.0,'hr-cl-04','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Hindustan Times","author_id":"hr-src-03","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.65,"label":"negative"},"keywords":["Pakistan","handler","NIA","encrypted","Ambala","supply"]}'::jsonb,NOW()-INTERVAL '14 days',NOW(),'org_cyber'),
('hr-ci-38','hr-stf-001','hr-src-13','http://ahmia.onion/haryana-drug-market','Dark web forum discussing Haryana drug routes','Dark web forum post discussing safest drug transport routes through Haryana. Mentions avoiding Ambala and using Hisar-Rohtak route instead. Users share tips on evading police checkpoints. Post from 2 weeks ago.', md5('hr-ci-38'),'en',NOW()-INTERVAL '11 days',5.0,'hr-cl-04','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Ahmia Onion","author_id":"hr-src-13","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.5,"label":"negative"},"keywords":["dark web","routes","Haryana","Hisar","Rohtak","checkpoints"]}'::jsonb,NOW()-INTERVAL '11 days',NOW(),'org_cyber'),
('hr-ci-39','hr-stf-001','hr-src-07','https://t.me/haryana_crime_updates/590','Crypto used for drug payments','Drug syndicates shifting to cryptocurrency payments. USDT transfers via P2P platforms. No bank trail. STF cyber cell tracking but blockchain analysis capabilities limited. Handle @crypto_maal_786 active on Telegram.', md5('hr-ci-39'),'en',NOW()-INTERVAL '8 days',25.0,'hr-cl-04','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@haryana_crime_updates","author_id":"haryana_crime_updates","engagement":{"likes":20,"comments":35,"shares":0,"views":780,"forwards":16},"sentiment":{"compound":-0.5,"label":"negative"},"keywords":["cryptocurrency","USDT","P2P","blockchain","Telegram","drug payments"]}'::jsonb,NOW()-INTERVAL '8 days',NOW(),'org_cyber'),
('hr-ci-40','hr-stf-001','hr-src-04','https://amarujala.com/haryana-border-fencing','Haryana demands border fencing with Punjab','Amar Ujala: Haryana demands enhanced border fencing and checkpoints along Punjab border specifically for drug control. CM writes to Centre citing 300% increase in drug seizures from Punjab direction.', md5('hr-ci-40'),'en',NOW()-INTERVAL '5 days',72.0,'hr-cl-04','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Amar Ujala","author_id":"hr-src-04","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":-0.3,"label":"negative"},"keywords":["border fencing","Punjab","CM","drug control","checkpoints"]}'::jsonb,NOW()-INTERVAL '5 days',NOW(),'org_cyber'),

-- ── Cluster 5: Youth Anti-Drug Movement and Rehabilitation (8 items) ──
('hr-ci-41','hr-stf-001','hr-src-05','https://indianexpress.com/haryana-youth-anti-drug','Youth-led Drug Free Haryana campaign','Indian Express: College students launch #DrugFreeHaryana campaign on social media. Viral videos showing drug impact on families. 50,000 signatures on petition to CM. Campaign started in Kurukshetra University, spreading statewide.', md5('hr-ci-41'),'en',NOW()-INTERVAL '20 days',78.0,'hr-cl-05','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Indian Express","author_id":"hr-src-05","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.4,"label":"positive"},"keywords":["DrugFreeHaryana","youth","campaign","petition","Kurukshetra"]}'::jsonb,NOW()-INTERVAL '20 days',NOW(),'org_cyber'),
('hr-ci-42','hr-stf-001','hr-src-07','https://t.me/haryana_crime_updates/572','Ex-addicts share recovery stories','Powerful: Former chitta addicts sharing recovery stories on Telegram and YouTube. Documenting their journey from addiction to rehabilitation. One video from Ambala youth has 50K views. Inspiring others to seek help.', md5('hr-ci-42'),'en',NOW()-INTERVAL '18 days',25.0,'hr-cl-05','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@haryana_crime_updates","author_id":"haryana_crime_updates","engagement":{"likes":78,"comments":45,"shares":0,"views":2100,"forwards":30},"sentiment":{"compound":0.5,"label":"positive"},"keywords":["recovery","addicts","stories","rehabilitation","Ambala","YouTube"]}'::jsonb,NOW()-INTERVAL '18 days',NOW(),'org_cyber'),
('hr-ci-43','hr-stf-001','hr-src-02','https://jagran.com/haryana-ngo-rehab','NGOs fill gap in government drug rehab','Dainik Jagran: Private NGOs running 15 drug rehabilitation centers across Haryana, filling gap left by inadequate government facilities. Nasha Mukti Abhiyan organization treating 500 patients monthly.', md5('hr-ci-43'),'en',NOW()-INTERVAL '15 days',75.0,'hr-cl-05','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Dainik Jagran","author_id":"hr-src-02","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.2,"label":"positive"},"keywords":["NGO","rehabilitation","Nasha Mukti","treatment","government gap"]}'::jsonb,NOW()-INTERVAL '15 days',NOW(),'org_cyber'),
('hr-ci-44','hr-stf-001','hr-src-12','https://youtube.com/watch?v=anti_drug_rally','Anti-drug rally in Karnal — 10,000 march','Haryana Police YouTube: Video coverage of massive anti-drug rally in Karnal. 10,000 citizens march. CM addresses crowd, promises zero tolerance. STF IG announces reward scheme for drug tip-offs. Phone: +91-98765-33333.', md5('hr-ci-44'),'en',NOW()-INTERVAL '12 days',85.0,'hr-cl-05','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Haryana Police Press","author_id":"hr-src-12","engagement":{"likes":230,"comments":78,"shares":56,"views":15000},"sentiment":{"compound":0.35,"label":"positive"},"keywords":["anti-drug rally","Karnal","CM","STF","reward","tip-offs"]}'::jsonb,NOW()-INTERVAL '12 days',NOW(),'org_cyber'),
('hr-ci-45','hr-stf-001','hr-src-09','https://t.me/chitta_alert_hrpb/60','Community watch groups in Ambala villages','Community watch groups active in 25 Ambala villages. Night patrols catch 3 peddlers this week. Panchayats passing resolutions banning known drug users from village events. Social pressure working alongside police action.', md5('hr-ci-45'),'en',NOW()-INTERVAL '10 days',12.0,'hr-cl-05','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@chitta_alert_hrpb","author_id":"chitta_alert_hrpb","engagement":{"likes":34,"comments":28,"shares":0,"views":680,"forwards":12},"sentiment":{"compound":0.25,"label":"positive"},"keywords":["community watch","Ambala","panchayat","peddlers","social pressure"]}'::jsonb,NOW()-INTERVAL '10 days',NOW(),'org_cyber'),
('hr-ci-46','hr-stf-001','hr-src-01','https://tribuneindia.com/haryana-school-awareness','Drug awareness program in 500 Haryana schools','Tribune India: Haryana Education Dept launches drug awareness program in 500 schools across Ambala, Karnal, and Panchkula. Police officers give talks. Students take anti-drug pledge. Peer counselor program introduced.', md5('hr-ci-46'),'en',NOW()-INTERVAL '8 days',82.0,'hr-cl-05','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Tribune India","author_id":"hr-src-01","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.5,"label":"positive"},"keywords":["school","awareness","Ambala","Karnal","Panchkula","pledge"]}'::jsonb,NOW()-INTERVAL '8 days',NOW(),'org_cyber'),
('hr-ci-47','hr-stf-001','hr-src-06','https://t.me/punjab_drug_watch/255','Rehabilitation success rate improving','Good news: Haryana drug rehab success rate improving to 45% from 30% last year. New AIIMS-protocol detox program showing results. Key factor: follow-up support after discharge. Family involvement critical.', md5('hr-ci-47'),'en',NOW()-INTERVAL '6 days',20.0,'hr-cl-05','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"@punjab_drug_watch","author_id":"punjab_drug_watch","engagement":{"likes":42,"comments":20,"shares":0,"views":950,"forwards":14},"sentiment":{"compound":0.45,"label":"positive"},"keywords":["rehabilitation","success rate","AIIMS","detox","follow-up"]}'::jsonb,NOW()-INTERVAL '6 days',NOW(),'org_cyber'),
('hr-ci-48','hr-stf-001','hr-src-03','https://hindustantimes.com/chandigarh/sports-anti-drug','Sports as anti-drug tool in Haryana','Hindustan Times: Sports department launches "Khelo, Nasha Nahi" initiative in Ambala and Karnal. Free coaching in wrestling, kabaddi, boxing for at-risk youth. 2000 enrolled in first month. Athletes share anti-drug messages.', md5('hr-ci-48'),'en',NOW()-INTERVAL '3 days',80.0,'hr-cl-05','{"classification":"RESTRICTED","domain":"narcotics","owner_org":"cyber","author_handle":"Hindustan Times","author_id":"hr-src-03","engagement":{"likes":0,"comments":0,"shares":0,"views":0},"sentiment":{"compound":0.6,"label":"positive"},"keywords":["sports","Khelo Nasha Nahi","wrestling","kabaddi","Ambala","Karnal"]}'::jsonb,NOW()-INTERVAL '3 days',NOW(),'org_cyber')
